const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['沒有人當清算人怎麼辦','縣府）選任'],['清算人找不到人當怎麼辦','第27條'],['沒人要當清算人','選任'],
['解散前理事長跑掉了怎麼辦','30日內'],['理事長失聯了想解散怎麼辦','第15條'],['會長聯絡不上要解散怎麼辦','連署'],
['沒錢的協會怎麼解散','沒有以財產多寡'],['協會沒有經費可以解散嗎','第59條'],['帳戶沒錢了可以結束協會嗎','三分之二'],
['會員剩不到幾人會被解散','沒有規定「會員少於幾人'],['會員只剩十個人會被廢止嗎','第8條'],['會員太少會被解散嗎','第58條'],
['協會解散跟註銷一樣嗎','第18條'],['解散和註銷有什麼不同','證書'],
['解散之後要做什麼清算','第27條'],['清算要怎麼進行','清算人'],['協會清算流程是什麼','民法']];
const no=['合作社沒有人當清算人怎麼辦','社區發展協會沒錢怎麼解散','清算要多久','清算完要向誰報告','解散後欠錢怎麼辦','理事長跑掉了怎麼辦','解散要登報嗎','公會會員剩幾人會被解散','解散後還要報稅嗎','勸募沒錢怎麼辦','協會解散後的印章怎麼辦'];
const mine=/^(清算人找不到人當|理事長失聯也要解散|沒有錢也可以解散|會員少到幾個人|解散和註銷不一樣|解散後的清算：)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const x=a&&a.title?(a.title+a.summary):'';if(!x.includes(e)||!a.direct||!mine.test(a.title)){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&a.title&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
